import{_ as e,o as t,c as a,ag as i}from"./chunks/framework.7He2WLS4.js";const f=JSON.parse('{"title":"Sessions","description":"Organize and manage captured traffic into named sessions in NectoProxy.","frontmatter":{"title":"Sessions","description":"Organize and manage captured traffic into named sessions in NectoProxy."},"headers":[],"relativePath":"features/sessions.md","filePath":"features/sessions.md","lastUpdated":1772297611000}'),n={name:"features/sessions.md"};function o(r,s,l,d,c,h){return t(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h1><p>Sessions let you <strong>organize captured traffic</strong> into separate, named containers. Instead of having all captured traffic in a single, ever-growing list, you can create distinct sessions for different debugging tasks, testing scenarios, or time periods. Switch between sessions without losing data, and export or delete sessions when you are done.</p><h2 id="what-is-a-session" tabindex="-1">What is a Session? <a class="header-anchor" href="#what-is-a-session" aria-label="Permalink to &quot;What is a Session?&quot;">​</a></h2><p>A session is a named collection of captured traffic entries. Think of sessions as folders or workspaces for your network traffic:</p><ul><li>Each session has its own traffic list</li><li>Traffic is captured into the <strong>active session</strong></li><li>You can create, switch, rename, and delete sessions</li><li>Sessions persist across NectoProxy restarts</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Using sessions keeps your work organized. Instead of scrolling through thousands of unrelated requests to find what you need, create a new session for each debugging task and keep your traffic focused.</p></div><h2 id="creating-sessions" tabindex="-1">Creating Sessions <a class="header-anchor" href="#creating-sessions" aria-label="Permalink to &quot;Creating Sessions&quot;">​</a></h2><h3 id="creating-a-new-session" tabindex="-1">Creating a New Session <a class="header-anchor" href="#creating-a-new-session" aria-label="Permalink to &quot;Creating a New Session&quot;">​</a></h3><ol><li>Click the <strong>Sessions</strong> button in the NectoProxy toolbar</li><li>Click <strong>New Session</strong></li><li>Enter a descriptive name for the session</li><li>The new session becomes the active session immediately</li></ol><h3 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h3><p>Choose session names that describe the purpose or context of the captured traffic. Good examples:</p><table tabindex="0"><thead><tr><th>Session Name</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Login Flow Investigation</code></td><td>Debugging authentication issues</td></tr><tr><td><code>API v2 Migration Testing</code></td><td>Comparing old and new API behavior</td></tr><tr><td><code>Performance Baseline 2025-01-15</code></td><td>Capturing baseline performance metrics</td></tr><tr><td><code>Bug #1234 Reproduction</code></td><td>Reproducing a specific bug report</td></tr><tr><td><code>Security Review - Checkout</code></td><td>Security scanning the checkout flow</td></tr><tr><td><code>Mobile App Traffic</code></td><td>Traffic from a mobile application</td></tr></tbody></table><details class="details custom-block"><summary>Default Session</summary><p>When NectoProxy starts, a default session is created automatically. You can rename the default session or create new ones as needed. If you do not create any sessions explicitly, all traffic is captured into the default session.</p></details><h2 id="switching-between-sessions" tabindex="-1">Switching Between Sessions <a class="header-anchor" href="#switching-between-sessions" aria-label="Permalink to &quot;Switching Between Sessions&quot;">​</a></h2><p>Click on any session in the sessions panel to make it the <strong>active session</strong>. The traffic list immediately updates to show the entries from the selected session.</p><p><strong>Key behaviors when switching:</strong></p><ul><li>Captured traffic is always added to the <strong>active</strong> session</li><li>Switching sessions does not delete or modify traffic in other sessions</li><li>You can quickly switch back and forth between sessions to compare traffic</li><li>The previously active session&#39;s traffic remains intact</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When you switch to a different session, new traffic is captured into the newly active session. If you need to capture traffic into a specific session, make sure it is the active session before starting your test.</p></div><h2 id="active-session-indicator" tabindex="-1">Active Session Indicator <a class="header-anchor" href="#active-session-indicator" aria-label="Permalink to &quot;Active Session Indicator&quot;">​</a></h2><p>The currently active session is clearly indicated in the NectoProxy UI:</p><ul><li>The session name is displayed in the toolbar</li><li>The active session is highlighted in the sessions panel</li><li>A visual indicator (such as a dot or bold text) marks the active session in the list</li></ul><p>This ensures you always know which session is receiving new traffic.</p><h2 id="session-statistics" tabindex="-1">Session Statistics <a class="header-anchor" href="#session-statistics" aria-label="Permalink to &quot;Session Statistics&quot;">​</a></h2><p>Each session displays summary statistics so you can quickly assess its contents:</p><table tabindex="0"><thead><tr><th>Statistic</th><th>Description</th></tr></thead><tbody><tr><td><strong>Request Count</strong></td><td>Total number of HTTP requests captured in the session</td></tr><tr><td><strong>Total Bytes</strong></td><td>Combined size of all request and response bodies in the session</td></tr><tr><td><strong>Created</strong></td><td>When the session was created</td></tr><tr><td><strong>Last Activity</strong></td><td>When the most recent request was captured</td></tr></tbody></table><details class="details custom-block"><summary>Example: Sessions Panel View</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sessions</span></span>
<span class="line"><span>========</span></span>
<span class="line"><span></span></span>
<span class="line"><span>* Login Flow Investigation        (active)</span></span>
<span class="line"><span>  42 requests | 1.2 MB | Last: 2 min ago</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  API v2 Migration Testing</span></span>
<span class="line"><span>  187 requests | 15.4 MB | Last: 1 hour ago</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Performance Baseline 2025-01-15</span></span>
<span class="line"><span>  523 requests | 48.7 MB | Last: Yesterday</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Bug #1234 Reproduction</span></span>
<span class="line"><span>  12 requests | 340 KB | Last: 3 days ago</span></span></code></pre></div></details><h2 id="managing-sessions" tabindex="-1">Managing Sessions <a class="header-anchor" href="#managing-sessions" aria-label="Permalink to &quot;Managing Sessions&quot;">​</a></h2><h3 id="renaming-a-session" tabindex="-1">Renaming a Session <a class="header-anchor" href="#renaming-a-session" aria-label="Permalink to &quot;Renaming a Session&quot;">​</a></h3><ol><li>Right-click on the session in the sessions panel</li><li>Select <strong>Rename</strong></li><li>Enter the new name</li><li>Press Enter to confirm</li></ol><h3 id="deleting-sessions" tabindex="-1">Deleting Sessions <a class="header-anchor" href="#deleting-sessions" aria-label="Permalink to &quot;Deleting Sessions&quot;">​</a></h3><ol><li>Right-click on the session</li><li>Select <strong>Delete Session</strong></li><li>Confirm the deletion</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Deleting a session permanently removes all captured traffic data within it. This action cannot be undone. Export important sessions before deleting them.</p></div><p>You cannot delete the active session if it is the only session. Create a new session first, switch to it, and then delete the old one.</p><h3 id="clearing-a-session" tabindex="-1">Clearing a Session <a class="header-anchor" href="#clearing-a-session" aria-label="Permalink to &quot;Clearing a Session&quot;">​</a></h3><p>To remove all traffic from a session without deleting the session itself:</p><ol><li>Make the session active</li><li>Click <strong>Clear</strong> in the traffic list toolbar</li><li>The session&#39;s traffic list is emptied, but the session remains</li></ol><p>This is useful for starting a fresh capture within an existing session.</p><h2 id="exporting-sessions" tabindex="-1">Exporting Sessions <a class="header-anchor" href="#exporting-sessions" aria-label="Permalink to &quot;Exporting Sessions&quot;">​</a></h2><p>Sessions can be exported for archiving, sharing with teammates, or importing into other tools.</p><h3 id="export-as-har" tabindex="-1">Export as HAR <a class="header-anchor" href="#export-as-har" aria-label="Permalink to &quot;Export as HAR&quot;">​</a></h3><p>Export all traffic in a session to a <a href="./har-export-import.html">HAR file</a>:</p><ol><li>Right-click on the session</li><li>Select <strong>Export as HAR</strong></li><li>Choose a save location and filename</li><li>The entire session&#39;s traffic is saved as a HAR 1.2 file</li></ol><h3 id="what-is-included-in-exports" tabindex="-1">What is Included in Exports <a class="header-anchor" href="#what-is-included-in-exports" aria-label="Permalink to &quot;What is Included in Exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Data</th><th>Included</th></tr></thead><tbody><tr><td>All request/response pairs</td><td>Yes</td></tr><tr><td>Headers and bodies</td><td>Yes</td></tr><tr><td>Timing data</td><td>Yes</td></tr><tr><td>Annotations</td><td>Yes</td></tr><tr><td>Session name and metadata</td><td>Yes</td></tr></tbody></table><h2 id="practical-workflows" tabindex="-1">Practical Workflows <a class="header-anchor" href="#practical-workflows" aria-label="Permalink to &quot;Practical Workflows&quot;">​</a></h2><h3 id="workflow-1-bug-investigation" tabindex="-1">Workflow 1: Bug Investigation <a class="header-anchor" href="#workflow-1-bug-investigation" aria-label="Permalink to &quot;Workflow 1: Bug Investigation&quot;">​</a></h3><ol><li><strong>Create a session</strong> named <code>Bug #456 Investigation</code></li><li><strong>Reproduce the bug</strong> while capturing traffic</li><li><strong>Annotate</strong> the key requests with your findings</li><li><strong>Share</strong> by exporting the session as HAR and attaching it to the bug ticket</li><li><strong>Keep the session</strong> until the bug is resolved for reference</li></ol><h3 id="workflow-2-before-after-comparison" tabindex="-1">Workflow 2: Before/After Comparison <a class="header-anchor" href="#workflow-2-before-after-comparison" aria-label="Permalink to &quot;Workflow 2: Before/After Comparison&quot;">​</a></h3><ol><li><strong>Create a session</strong> named <code>Before Deploy v2.5</code></li><li><strong>Capture traffic</strong> from the current version</li><li><strong>Deploy</strong> the new version</li><li><strong>Create a new session</strong> named <code>After Deploy v2.5</code></li><li><strong>Capture traffic</strong> from the new version</li><li><strong>Switch</strong> between sessions to compare behavior</li><li>Use <a href="./request-comparison.html">Request Comparison</a> across sessions</li></ol><h3 id="workflow-3-organized-development" tabindex="-1">Workflow 3: Organized Development <a class="header-anchor" href="#workflow-3-organized-development" aria-label="Permalink to &quot;Workflow 3: Organized Development&quot;">​</a></h3><p>Maintain separate sessions for different parts of your development work:</p><table tabindex="0"><thead><tr><th>Session</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Frontend Dev</code></td><td>Traffic while developing the frontend</td></tr><tr><td><code>API Testing</code></td><td>Direct API call testing</td></tr><tr><td><code>Third-Party Integration</code></td><td>Traffic to/from external services</td></tr><tr><td><code>Performance Profiling</code></td><td>Measuring response times and payload sizes</td></tr></tbody></table><p>Switch between sessions as you move between tasks throughout the day.</p><h3 id="workflow-4-team-collaboration" tabindex="-1">Workflow 4: Team Collaboration <a class="header-anchor" href="#workflow-4-team-collaboration" aria-label="Permalink to &quot;Workflow 4: Team Collaboration&quot;">​</a></h3><ol><li>Each team member creates sessions for their work</li><li>When an issue is found, the session is exported as HAR</li><li>Other team members import the HAR into their own NectoProxy instance</li><li>The original annotations and context are preserved</li></ol><h2 id="session-lifecycle" tabindex="-1">Session Lifecycle <a class="header-anchor" href="#session-lifecycle" aria-label="Permalink to &quot;Session Lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create Session</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     v</span></span>
<span class="line"><span>Set as Active ----&gt; Capture Traffic</span></span>
<span class="line"><span>     |                    |</span></span>
<span class="line"><span>     v                    v</span></span>
<span class="line"><span>Switch Away         Traffic Stored</span></span>
<span class="line"><span>     |                    |</span></span>
<span class="line"><span>     v                    v</span></span>
<span class="line"><span>Switch Back         Export (HAR)</span></span>
<span class="line"><span>     |                    |</span></span>
<span class="line"><span>     v                    v</span></span>
<span class="line"><span>Clear or Delete     Share with Team</span></span></code></pre></div><h2 id="interaction-with-other-features" tabindex="-1">Interaction with Other Features <a class="header-anchor" href="#interaction-with-other-features" aria-label="Permalink to &quot;Interaction with Other Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Interaction</th></tr></thead><tbody><tr><td><strong>Traffic Inspection</strong></td><td>Shows traffic from the active session only</td></tr><tr><td><strong>Rules Engine</strong></td><td>Rules apply regardless of which session is active</td></tr><tr><td><strong>Breakpoints</strong></td><td>Breakpoints apply regardless of which session is active</td></tr><tr><td><strong>Search</strong></td><td>Filter bar searches within the active session; global search can search across all sessions</td></tr><tr><td><strong>Dashboard</strong></td><td>Dashboard displays statistics for the active session</td></tr><tr><td><strong>Annotations</strong></td><td>Annotations are stored per-entry within their session</td></tr><tr><td><strong>HAR Export</strong></td><td>Exports the selected session&#39;s traffic</td></tr></tbody></table><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Sessions are stored locally in NectoProxy&#39;s data directory. They persist across proxy restarts and are available until explicitly deleted. Large sessions with many captured entries consume disk space proportional to the amount of captured traffic data.</p></div>`,61)])])}const g=e(n,[["render",o]]);export{f as __pageData,g as default};
